CREATE DATABASE IF NOT EXISTS sammy_tech_store CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE sammy_tech_store;

CREATE TABLE administrators (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, username VARCHAR(60) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE categories (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, slug VARCHAR(120) NOT NULL UNIQUE, description VARCHAR(255) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE products (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, category_id INT UNSIGNED NOT NULL, name VARCHAR(150) NOT NULL, sku VARCHAR(60) NOT NULL UNIQUE, short_description VARCHAR(255) NOT NULL, price DECIMAL(12,2) NOT NULL, stock_quantity INT NOT NULL DEFAULT 0, featured TINYINT(1) NOT NULL DEFAULT 0, status ENUM('active','draft','out_of_stock') NOT NULL DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_products_category FOREIGN KEY (category_id) REFERENCES categories(id));
CREATE TABLE orders (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_number VARCHAR(30) NOT NULL UNIQUE, customer_name VARCHAR(150) NOT NULL, phone VARCHAR(50) NOT NULL, email VARCHAR(150) NULL, delivery_method ENUM('pickup','delivery') NOT NULL DEFAULT 'pickup', payment_method ENUM('cash','mobile_money','bank_transfer') NOT NULL DEFAULT 'cash', status ENUM('new','confirmed','processing','ready','completed','cancelled') NOT NULL DEFAULT 'new', total_amount DECIMAL(12,2) NOT NULL, notes TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE order_items (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id INT UNSIGNED NOT NULL, product_id INT UNSIGNED NOT NULL, product_name VARCHAR(150) NOT NULL, quantity INT UNSIGNED NOT NULL DEFAULT 1, unit_price DECIMAL(12,2) NOT NULL, CONSTRAINT fk_item_order FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE, CONSTRAINT fk_item_product FOREIGN KEY (product_id) REFERENCES products(id));

